INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Erweiterungsprogrammierung nur für Betriebssysteme gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Anwendungen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Erweiterungsprogrammierung?', 3, '[{"text": "Funktionalität bestehender Software erweitern", "correct": true, "because": "Add-ons, Plugins"}, {"text": "Neue Software erstellen", "correct": false, "because": "Erweiterung, kein Neubau"}, {"text": "Hardware optimieren", "correct": false, "because": "Softwarefokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutzt die Erweiterungsprogrammierung?', 5, '[{"text": "APIs", "correct": true, "because": "Schnittstellen nutzen"}, {"text": "Plugins", "correct": true, "because": "Modulare Erweiterung"}, {"text": "Papierdokumentation", "correct": false, "because": "Nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Erweiterungsprogrammierung nutzt bestehende Software. b) Sie erfordert immer neue Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erweiterungsprogrammierung?', 4, '[{"text": "Schnittstellen", "correct": false, "because": "Integration nötig"}, {"text": "Kompatibilität", "correct": false, "because": "Anpassung erforderlich"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Erweiterungsprogrammierung immer eigenständig läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Basissoftware"}, {"text": "Ja", "correct": false, "because": "Integration nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für Erweiterungsprogrammierung?', 3, '[{"text": "API-Nutzung", "correct": true, "because": "Schnittstellenintegration"}, {"text": "Hardware-Tuning", "correct": false, "because": "Nicht Software"}, {"text": "Papierdokumentation", "correct": false, "because": "Kein Programmieransatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Erweiterungsprogrammierung?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung möglich"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Modularität"}, {"text": "Maximale Leistung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Erweiterungsprogrammierung erweitert Softwarefunktionen. b) Sie ist nur für Betriebssysteme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Anwendungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Erweiterungsprogrammierung?', 4, '[{"text": "API-Dokumentation", "correct": false, "because": "Schnittstellen verstehen"}, {"text": "Programmiersprache", "correct": false, "because": "Entwicklung nötig"}, {"text": "Physische Hardware", "correct": true, "because": "Softwarefokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Erweiterungsprogrammierung nur für große Softwareprojekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Erweiterungen"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gibt es für Erweiterungsprogrammierung?', 4, '[{"text": "Browser-Plugins", "correct": true, "because": "Z. B. AdBlock"}, {"text": "IDE-Erweiterungen", "correct": true, "because": "Z. B. VS Code"}, {"text": "Papierdokumente", "correct": false, "because": "Keine Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Erweiterungsprogrammierung keine APIs benötigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "APIs oft nötig"}, {"text": "Ja", "correct": false, "because": "Schnittstellen üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erweiterungsprogrammierung?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Integration sicherstellen"}, {"text": "Papierformat", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Erweiterungsprogrammierung nutzt bestehende Systeme. b) Sie erfordert immer neue Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erweiterung, kein Neubau"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools nutzt die Erweiterungsprogrammierung?', 5, '[{"text": "SDKs", "correct": true, "because": "Entwicklungskits"}, {"text": "APIs", "correct": true, "because": "Schnittstellen"}, {"text": "Papierdrucker", "correct": false, "because": "Nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Erweiterungsprogrammierung unwichtig?', 3, '[{"text": "Schnittstellen", "correct": false, "because": "Integration"}, {"text": "Programmierlogik", "correct": false, "because": "Funktionalität"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Erweiterungsprogrammierung eigenständig laufen?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Basissoftware"}, {"text": "Ja", "correct": false, "because": "Integration nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Erweiterungsprogrammierung für alle Software möglich ist?', 2, '[{"text": "Nein", "correct": true, "because": "API-Abhängig"}, {"text": "Ja", "correct": false, "because": "Nicht immer verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Erweiterungsprogrammierung zentral?', 4, '[{"text": "Schnittstellenintegration", "correct": true, "because": "Kernprinzip"}, {"text": "Neue Software", "correct": false, "because": "Erweiterung"}, {"text": "Physische Hardware", "correct": false, "because": "Softwarefokus"}]');
